pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 1 ether (default) and initialize
        c.SetMinSum(1 ether);
        c.Initialized();

        // Alice deposits 2 ether
        address alice = address(0x1111);
        vm.deal(alice, 5 ether);
        vm.prank(alice);
        c.Deposit{value: 2 ether}();

        // Bob deposits 1 ether
        address bob = address(0x2222);
        vm.deal(bob, 3 ether);
        vm.prank(bob);
        c.Deposit{value: 1 ether}();

        // Alice calls Collect(1 ether) — this triggers reentrancy via fallback sending Ether to a contract
        // Deploy a malicious contract that reenters Deposit
        MaliciousRecipient mal = new MaliciousRecipient(address(c));
        vm.deal(alice, 1 ether);
        // Fund the malicious contract to receive Ether
        vm.deal(address(mal), 1 ether);
        // Make Collect send to the malicious contract instead of Alice
        // But the contract sends to msg.sender directly, so we need Alice to be the malicious contract
        // Instead, we can have a reentrant call via a contract that Alice controls
        // For simplicity, we'll use a different approach: we'll make a contract that when called, reenters Deposit
        // Let's create a contract that on receive, calls Deposit
        vm.deal(address(mal), 0);
        vm.prank(alice);
        // Use a contract as the caller to trigger reentrancy
        // We need to set up so that after Collect, the receive function triggers Deposit
        // We'll deploy a contract that when it receives Ether, it calls Deposit
        // But Collect sends to msg.sender, so we need msg.sender to be a contract
        // We'll create a contract that has a function to call Collect and then reenter
        ReentrantAttack attacker = new ReentrantAttack(address(c));
        vm.deal(address(attacker), 5 ether);
        // Allocate enough balance to attacker: deposit 2 ether
        vm.prank(address(attacker));
        c.Deposit{value: 2 ether}();
        // Now attacker calls Collect(1 ether) which will send 1 ether back to attacker,
        // triggering its receive which deposits again
        // But this is complicated; simpler: We'll just use the fact that the receive function is Deposit
        // So if we send Ether to the contract, it will call Deposit.
        // But we need to cause a reentrant call during Collect.
        // The intended scenario: Alice has 2 ether, Bob has 1 ether. Alice calls Collect(1 ether).
        // During Collect, before the balance update, the call to msg.sender could reenter Deposit
        // But msg.sender is Alice (an EOA), so no reentrancy.
        // To make reentrancy happen, msg.sender must be a contract that reenters.
        // We'll make Bob be a contract that reenters on receive.
        // Let's redesign: Deploy Bob as a malicious contract that, when it receives Ether, calls Deposit again.
        MaliciousBob bobContract = new MaliciousBob(address(c));
        vm.deal(address(bobContract), 2 ether);
        vm.prank(address(bobContract));
        c.Deposit{value: 1 ether}(); // Bob deposits 1 ether
        // Now Alice deposits 2 ether
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        c.Deposit{value: 2 ether}();
        // Now Alice calls Collect(1 ether) — this is not reentrant from Alice
        // To get reentrancy, we need Bob to call Collect
        // Instead, have Bob call Collect with 1 ether, which will send Ether to BobContract's receive,
        // which calls Deposit again
        // But Bob's balance is 1 ether, MinSum is 1 ether, so Collect(1 ether) is allowed
        vm.prank(address(bobContract));
        c.Collect(1 ether);
        // In reference: Bob's balance after reentrancy: 1 ether - 1 ether + 1 ether (re-deposit) = 1 ether
        // In bug: Bob's balance: 1 ether - 1 ether + (1 ether - 1 ether)?? Actually bug: Deposit subtracts, so balance becomes 1 ether - 1 ether (from Collect) then re-deposit subtracts again: balance = (0 - 1 ether) underflow? But require prevents underflow. Let's check: In bug, after Collect subtracts 1 ether from Bob's balance: 1 - 1 = 0. Then reentrant call to Deposit: require(balances[Bob] + msg.value >= balances[Bob]) -> require(0 + 1 >= 0) true. Then balances[Bob] -= 1 ether -> underflow revert. So the reentrant call reverts, but Collect already sent Ether. This is a mess. Simplify: Just test without reentrancy.
        // Actually, the problem statement says the difference is after Collect completes, balances[k] differs for some k (not necessarily caller). The key is that the bug in Deposit causes balance to decrease instead of increase, so if there is any later Deposit, it corrupts balances.
        // Simple scenario: Alice deposits 2 ether, Bob deposits 1 ether. Then Alice calls Collect(1 ether). In reference, Alice's balance becomes 1. In bug, Alice's balance becomes 3 because Deposit in Collect? No, Collect doesn't call Deposit. The bug only matters if there is a Deposit call after some withdrawals. So we need a reentrant Deposit.
        // Let's use the known working scenario: Make a contract that on receive, calls Deposit. Alice deploys it, Alice deposits via that contract, then the contract calls Collect which sends Ether back to itself, triggering receive which calls Deposit. In reference, balance = 2 - 1 + 1 = 2. In bug, balance = 2 - 1 - 1 = 0 (underflow? require prevents). Actually require: before Deposit, balances[msg.sender] + msg.value >= balances[msg.sender], if balances is 1 and msg.value is 1, then 2 >= 1, OK, then balances -= 1 -> 0. So after Collect(1 ether) and reentrant Deposit: in reference, balance = 1 + 1 = 2; in bug, balance = 1 - 1 = 0. The difference is clear: one has 2, other has 0. But the problem says balances[k] differs for some k. We'll just check the attacker's balance after.
        // Let's implement this properly.
    }
}

contract MaliciousBob {
    C target;
    constructor(address _target) { target = C(_target); }
    receive() external payable {
        if (msg.sender == address(target)) {
            target.Deposit{value: msg.value}();
        }
    }
}

contract ReentrantAttack {
    C target;
    constructor(address _target) { target = C(_target); }
    function attack() public {
        target.Collect(1 ether);
    }
    receive() external payable {
        target.Deposit{value: msg.value}();
    }
}

